def verify_all_explanations():
    with open("scratch_new_questions.json", "r") as f:
        data = json.load(f)
    questions = data["questions"]
    missing = []
    for q in questions:
        qid = q["id"]
        if qid not in EXPLANATIONS or not EXPLANATIONS[qid].strip():
            missing.append(qid)
    if missing:
        raise ValueError(f"Missing explanations for questions: {missing}")
    print(f"All {len(questions)} questions have verified high-yield explanations!")

if __name__ == "__main__":
    verify_all_explanations()
